{
  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall implement a multi-layer safety architecture including passive, active, and functional safety mechanisms to ensure collision protection and fail-safe operations.",
      "quality_axes": ["Safety", "Trustworthiness", "Responsibility"],
      "derived_from": ["SAF-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall execute a Minimal Risk Maneuver within 5 seconds upon detecting critical failures to safely pull over to a low-risk zone while ensuring speed and comfort.",
      "quality_axes": ["Safety", "Efficiency"],
      "derived_from": ["SAF-02", "EFF-03"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-03",
      "text": "The system shall continuously monitor Operational Design Domain compliance and issue a human takeover request when boundaries are approached.",
      "quality_axes": ["Safety", "Responsibility"],
      "derived_from": ["SAF-03"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-04",
      "text": "The system shall minimize jerk to less than 0.5 m/s³ during normal operation while allowing for flexibility in emergency maneuvers.",
      "quality_axes": ["Safety", "Efficiency"],
      "derived_from": ["SAF-04", "SAF-07"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-05",
      "text": "The system shall satisfy curvature constraints ($kappa$) to prevent rollover during maneuvers at all speeds.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-06",
      "text": "The system shall utilize iterative quadratic programming to handle non-convex obstacle constraints reliably within a response time of 100 milliseconds.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["SAF-06", "EFF-06"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-07",
      "text": "The system shall optimize path planning to achieve a reduction in average travel time while ensuring energy efficiency targets are met.",
      "quality_axes": ["Efficiency", "Sustainability"],
      "derived_from": ["EFF-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-08",
      "text": "The system shall maintain a jerk value below 0.5 m/s³ during normal operation to enhance passenger comfort.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-02"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-09",
      "text": "The system shall continuously monitor ODD compliance with a latency of no more than 100 milliseconds to ensure real-time responsiveness.",
      "quality_axes": ["Efficiency", "Safety"],
      "derived_from": ["EFF-04"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-10",
      "text": "The system shall achieve at least 95% success rate in optimal speed profile generation during path planning.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-11",
      "text": "The system shall implement end-to-end data encryption for all user data transmitted to protect privacy and ensure data integrity.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-12",
      "text": "The system shall log all access and modifications to critical data for auditability purposes.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-13",
      "text": "The system shall conduct regular security audits at least bi-annually to identify and mitigate potential vulnerabilities.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-05"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-14",
      "text": "The system shall ensure compliance with the Apollo Pilot Safety Report and EM Motion Planner specifications at all operational times.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-15",
      "text": "The system shall implement a multi-layer safety architecture that guarantees active monitoring and response to critical system failures.",
      "quality_axes": ["Safety", "Responsibility"],
      "derived_from": ["RES-02"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-16",
      "text": "The system shall document all safety and compliance-related decisions and changes for accountability and regulatory purposes.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-07"],
      "kaos_level": "tactical",
      "parent": null
    }
  ],
